{"id": "544c1372-42df-47c3-94d6-017428cd2baf", "instanceId": "5afab722-b08d-4f84-afc8-56ee7ee9e550", "title": "PnP - Search Results", "description": "Displays JSON based data using customizable templates", "dataVersion": "1.0", "properties": {"documentationLink":"https://microsoft-search.github.io/pnp-modern-search/","allowWebPartConnections":true,"selectedLayoutKey":"Cards","resultTypes":[],"dataSourceProperties":{"queryTemplate":"{searchTerms}dafds","enableQueryRules":false,"enableLocalization":false,"refinementFilters":"","selectedProperties":["Title","Path","DefaultEncodingURL","FileType","HitHighlightedSummary","HitHighlightedProperties","AuthorOWSUSER","owstaxidmetadataalltagsinfo","Created","UniqueID","NormSiteID","NormWebID","NormListID","NormUniqueID","ContentTypeId","contentclass","UserName","JobTitle","WorkPhone","SPSiteURL","SPWebUrl","SiteTitle","CreatedBy","HtmlFileType","SiteLogo","PictureThumbnailURL"],"resultSourceId":"8413cd39-2156-4e00-b54d-11efd9abdb89","hitHighlightedProperties":"","trimDuplicates":false,"sortList":[]},"queryTextSource":0,"layoutProperties":{"documentCardFields":[{"name":"Title","field":"title","value":"{{slot item @root.slots.Title}}","useHandlebarsExpr":true,"supportHtml":false},{"name":"Location","field":"location","value":"<a style="color:{{@root.theme.palette.themePrimary}};font-weight:600;font-family:'{{@root.theme.fonts.small.fontFamily}}'" href="{{slot item @root.slots.SPWebURL}}">{{slot item @root.slots.SiteTitle}}</a>","useHandlebarsExpr":true,"supportHtml":true},{"name":"Tags","field":"tags","value":"<style>
	.tags {
