		text-decoration: underline; 
		margin-right: auto; 
	}
	 .simpletags 
	{
		display: inline-block;
		padding: 2px 5px;
		margin-right: 5px;
		background-color: {{@root.theme.palette.neutralLight}};
		color: {{@root.theme.palette.neutralDark}};
		border-radius: 5px;
		font-size: 12px;
	}
</style>

{{#if (slot item @root.slots.Tags)}}
	<div class="tags">
		<pnp-icon data-name="Tag" aria-hidden="true" data-theme-variant="{{JSONstringify @root.theme}}"></pnp-icon>
		<div>
		    <!-- If the enableLocalization is on I assume that the Auto[property] is used -->
            {{#if @root.properties.dataSourceProperties.enableLocalization}}

                {{#each (split (slot item @root.slots.Tags) "ǂǂ") as |tag| }}
             <span class="simpletags">
                    {{trim tag}}

            </span>
                {{/each}}

            {{else}}    
			<!-- Check if value contains taxonomy format (L0|#) to determine separator -->
			{{#if (regex "L0\\|#" (slot item @root.slots.Tags))}}
				<!-- Taxonomy format: split by semicolon -->
				{{#each (split (slot item @root.slots.Tags) ";") as |tag| }}
				<span class="simpletags">
					{{getTagName (trim tag)}}
				</span>
				{{/each}}
			{{else}}
				<!-- Plain text format: display as-is -->
				<span class="simpletags">
					{{trim (slot item @root.slots.Tags)}}
				</span>
			{{/if}}
			{{/if}}
		</div>
	</div>
{{/if}}","useHandlebarsExpr":true,"supportHtml":true},{"name":"Preview Image","field":"previewImage","value":"{{slot item @root.slots.PreviewImageUrl}}","useHandlebarsExpr":true,"supportHtml":false},{"name":"Preview Url","field":"previewUrl","value":"{{slot item @root.slots.PreviewUrl}}","useHandlebarsExpr":true,"supportHtml":false},{"name":"Date","field":"date","value":"{{getDate (slot item @root.slots.Date) 'LL'}}","useHandlebarsExpr":true,"supportHtml":false},{"name":"Url","field":"href","value":"{{slot item @root.slots.PreviewUrl}}","useHandlebarsExpr":true,"supportHtml":false},{"name":"Author","field":"author","value":"{{slot item @root.slots.Author}}","useHandlebarsExpr":true,"supportHtml":false},{"name":"Profile Image Url","field":"profileImage","value":"/_layouts/15/userphoto.aspx?size=L&username={{getUserEmail (slot item @root.slots.Author)}}","useHandlebarsExpr":true,"supportHtml":false},{"name":"File Extension","field":"fileExtension","value":"{{slot item @root.slots.FileType}}","useHandlebarsExpr":true,"supportHtml":false},{"name":"Is Folder","field":"isContainer","value":"{{slot item @root.slots.IsFolder}}","useHandlebarsExpr":true,"supportHtml":false}],"isCompact":false,"showFileIcon":true,"enablePreview":false,"preferedCardNumberPerRow":3,"columnSizePercentage":33},"showSelectedFilters":false,"showResultsCount":true,"showBlankIfNoResult":false,"useMicrosoftGraphToolkit":false,"itemSelectionProps":{"allowItemSelection":false,"selectionMode":"AsDataFilter","allowMulti":false,"valuesOperator":"or","selectionPreservedOnEmptyClick":false},"extensibilityLibraryConfiguration":[{"name":"Default extensibility library","enabled":true,"id":"dc4f961b-dbe0-44b4-982d-5776bf99d015"}],"queryModifierConfiguration":[],"queryModifierProperties":{"endWhenSuccessfull":false},"selectedVerticalKeys":[],"useVerticals":false,"paging":{"itemsCountPerPage":10,"pagingRange":5,"showPaging":true,"hideDisabled":true,"hideFirstLastPages":false,"hideNavigation":false,"useNextLinks":f